import sys
from collections import deque

def bfs(n, m, k, grid):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    start = None
    end = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                end = (i, j)

    queue = deque([(start[0], start[1], '', set())])
    visited = set()
    visited.add((start[0], start[1], frozenset()))

    while queue:
        x, y, path, types = queue.popleft()

        if (x, y) == end:
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != 'S':
                new_types = types.copy()
                if grid[nx][ny] != 'T':
                    new_types.add(grid[nx][ny])
                if len(new_types) > k:
                    continue
                if (nx, ny, frozenset(new_types)) not in visited:
                    visited.add((nx, ny, frozenset(new_types)))
                    new_path = path + grid[nx][ny] if grid[nx][ny] != 'T' else path
                    queue.append((nx, ny, new_path, new_types))

    return '-1'

def main():
    import sys
    input = sys.stdin.read().split()
    n, m, k = map(int, input[:3])
    grid = input[3:]
    result = bfs(n, m, k, grid)
    print(result)

if __name__ == "__main__":
    main()
